    35→function parseTemplateMeta(templateData: string): TemplateMeta {
    36→  try {
    37→    const parsed = JSON.parse(templateData) as Record<string, unknown>;
    38→    return {
    39→      emoji: typeof parsed.emoji === "string" ? parsed.emoji : "📋",
    40→    };
    41→  } catch {
    42→    return { emoji: "📋" };
    43→  }
    44→}
