    87→// ─── Slug helper ──────────────────────────────────────────────────────────────
    88→
    89→async function generateUniqueSlug(shop: string, title: string): Promise<string> {
    90→  const base = title
    91→    .toLowerCase()
    92→    .replace(/[^a-z0-9]+/g, "-")
    93→    .replace(/^-|-$/g, "");
    94→  let slug = base;
    95→  let counter = 0;
    96→  while (await db.quiz.findFirst({ where: { shop, slug } })) {
    97→    counter++;
    98→    slug = `${base}-${counter}`;
    99→  }
   100→  return slug;
   101→}
