    27→// ─── Types ────────────────────────────────────────────────────────────────────
    28→
    29→type Provider = "klaviyo" | "mailchimp" | "omnisend" | "custom-webhook";
    30→
    31→interface IntegrationRecord {
    32→  id: string;
    33→  provider: Provider;
    34→  apiKey: string;
    35→  listId: string | null;
    36→  isActive: boolean;
    37→}
    38→
    39→interface ProviderConfig {
