     1→import { json, type ActionFunctionArgs, type LoaderFunctionArgs } from "react-router";
     2→import db from "../db.server";
     3→
     4→const CORS_HEADERS = {
     5→  "Access-Control-Allow-Origin": "*",
     6→  "Access-Control-Allow-Methods": "POST, OPTIONS",
     7→  "Access-Control-Allow-Headers": "Content-Type",
     8→} as const;
     9→
    10→function parseSafe<T>(str: string, fallback: T): T {
    11→  try {
    12→    return JSON.parse(str) as T;
    13→  } catch {
    14→    return fallback;
    15→  }
    16→}
    17→
    18→// Handle OPTIONS preflight — GET not allowed on this route
    19→export async function loader({ request }: LoaderFunctionArgs) {
    20→  if (request.method === "OPTIONS") {
    21→    return new Response(null, { status: 204, headers: CORS_HEADERS });
    22→  }
    23→  return json(
    24→    { error: "Method not allowed" },
    25→    { status: 405, headers: CORS_HEADERS },
    26→  );
    27→}
    28→
    29→interface SubmitAnswer {
    30→  questionId: string;
    31→  answerId?: string;
    32→  value?: unknown;
    33→}
    34→
    35→interface SubmitBody {
    36→  answers?: SubmitAnswer[];
    37→  email?: string;
    38→  sessionId?: string;
    39→  source?: string;
    40→  deviceType?: string;
    41→}
    42→
    43→export async function action({ request, params }: ActionFunctionArgs) {
    44→  if (request.method === "OPTIONS") {
    45→    return new Response(null, { status: 204, headers: CORS_HEADERS });
    46→  }
    47→
    48→  const { slug } = params;
    49→  const shop = new URL(request.url).searchParams.get("shop");
    50→
    51→  if (!slug || !shop) {
    52→    return json(
    53→      { error: "Missing slug or shop" },
    54→      { status: 400, headers: CORS_HEADERS },
    55→    );
    56→  }
    57→
    58→  // Validate shop domain format
    59→  if (!/^[a-z0-9-]+\.myshopify\.com$/.test(shop)) {
    60→    return json(
    61→      { error: "Invalid shop domain" },
    62→      { status: 400, headers: CORS_HEADERS },
    63→    );
    64→  }
    65→
    66→  let body: SubmitBody;
    67→  try {
    68→    body = (await request.json()) as SubmitBody;
    69→  } catch {
    70→    return json(
    71→      { error: "Invalid JSON body" },
    72→      { status: 400, headers: CORS_HEADERS },
    73→    );
    74→  }
    75→
    76→  try {
    77→    const quiz = await db.quiz.findFirst({
    78→      where: { shop, slug, status: "active" },
    79→      include: {
    80→        questions: {
    81→          include: { answers: { orderBy: { position: "asc" } } },
    82→          orderBy: { position: "asc" },
    83→        },
    84→        resultPages: { orderBy: { position: "asc" } },
    85→      },
    86→    });
    87→
    88→    if (!quiz) {
    89→      return json(
    90→        { error: "Quiz not found" },
    91→        { status: 404, headers: CORS_HEADERS },
    92→      );
    93→    }
    94→
    95→    // Check monthly response limit against plan
    96→    const startOfMonth = new Date();
    97→    startOfMonth.setDate(1);
    98→    startOfMonth.setHours(0, 0, 0, 0);
    99→
   100→    const sub = await db.subscription.findUnique({
   101→      where: { shop },
   102→      select: { planId: true },
   103→    });
   104→    const planId = sub?.planId ?? "free";
   105→    const limits: Record<string, number> = {
   106→      free: 100,
   107→      starter: 1000,
   108→      pro: 10000,
   109→      enterprise: 999999,
   110→    };
   111→    const responseLimit = limits[planId] ?? 100;
   112→    const monthlyCount = await db.quizResponse.count({
   113→      where: { shop, createdAt: { gte: startOfMonth } },
   114→    });
   115→
   116→    if (monthlyCount >= responseLimit) {
   117→      return json(
   118→        { error: "Response limit reached for this store" },
   119→        { status: 429, headers: CORS_HEADERS },
   120→      );
   121→    }
   122→
   123→    const answers = body.answers ?? [];
   124→    const email = typeof body.email === "string" && body.email.trim() ? body.email.trim() : null;
   125→    const sessionId =
   126→      typeof body.sessionId === "string" && body.sessionId.trim()
   127→        ? body.sessionId
   128→        : crypto.randomUUID();
   129→
   130→    // Calculate score and aggregate product tags
   131→    let totalScore = 0;
   132→    const productTagCounts: Record<string, number> = {};
   133→
   134→    for (const answer of answers) {
   135→      if (!answer.answerId) continue;
   136→      const answerRecord = await db.answer.findUnique({
   137→        where: { id: answer.answerId },
   138→      });
   139→      if (!answerRecord) continue;
   140→      totalScore += answerRecord.score;
   141→      const tags = parseSafe(answerRecord.productTags, [] as string[]);
   142→      for (const tag of tags) {
   143→        productTagCounts[tag] = (productTagCounts[tag] ?? 0) + 1;
   144→      }
   145→    }
   146→
   147→    // Rank tags by frequency
   148→    const topTags = Object.entries(productTagCounts)
   149→      .sort(([, a], [, b]) => b - a)
   150→      .map(([tag]) => tag);
   151→
   152→    // Find the best matching result page
   153→    let matchedResultPage =
   154→      quiz.resultPages.find((rp) => {
   155→        if (
   156→          rp.type === "score-range" &&
   157→          rp.minScore != null &&
   158→          rp.maxScore != null
   159→        ) {
   160→          return totalScore >= rp.minScore && totalScore <= rp.maxScore;
   161→        }
   162→        if (rp.type === "tag-match") {
   163→          const matchTags = parseSafe(rp.matchTags, [] as string[]);
   164→          return topTags.some((tag) => matchTags.includes(tag));
   165→        }
   166→        return false;
   167→      }) ?? quiz.resultPages[0];
   168→
   169→    if (!matchedResultPage) {
   170→      return json(
   171→        { error: "No result pages configured for this quiz" },
   172→        { status: 400, headers: CORS_HEADERS },
   173→      );
   174→    }
   175→
   176→    // Fetch recommended products from synced catalog
   177→    const topTagsList = topTags.slice(0, 5);
   178→    const products =
   179→      topTagsList.length > 0
   180→        ? await db.productMapping.findMany({
   181→            where: {
   182→              shop,
   183→              status: "active",
   184→              OR: topTagsList.map((tag) => ({ tags: { contains: tag } })),
   185→            },
   186→            take: matchedResultPage.productLimit,
   187→            orderBy: { score: "desc" },
   188→          })
   189→        : [];
   190→
   191→    const recommendedProductGids = products.map((p) => p.productGid);
   192→
   193→    // Persist the quiz response
   194→    await db.quizResponse.create({
   195→      data: {
   196→        quizId: quiz.id,
   197→        shop,
   198→        sessionId,
   199→        email,
   200→        answers: JSON.stringify(answers),
   201→        score: totalScore,
   202→        recommendedProducts: JSON.stringify(recommendedProductGids),
   203→        completedAt: new Date(),
   204→        source: typeof body.source === "string" ? body.source : "embed",
   205→        deviceType:
   206→          typeof body.deviceType === "string" ? body.deviceType : null,
   207→      },
   208→    });
   209→
   210→    // Increment quiz completion counter
   211→    await db.quiz.update({
   212→      where: { id: quiz.id },
   213→      data: { completions: { increment: 1 } },
   214→    });
   215→
   216→    // Emit analytics event
   217→    await db.analyticsEvent.create({
   218→      data: {
   219→        shop,
   220→        quizId: quiz.id,
   221→        eventType: "quiz_completed",
   222→        sessionId,
   223→        data: JSON.stringify({
   224→          resultPageId: matchedResultPage.id,
   225→          resultPageTitle: matchedResultPage.title,
   226→          score: totalScore,
   227→        }),
   228→      },
   229→    });
   230→
   231→    // Sync email — fire and forget, never blocks the response
   232→    if (email) {
   233→      import("../services/email.server")
   234→        .then(({ syncToEmailProvider }) => {
   235→          syncToEmailProvider(shop, email, {
   236→            quizTitle: quiz.title,
   237→            quizSlug: quiz.slug,
   238→            resultPageTitle: matchedResultPage!.title,
   239→            score: totalScore,
   240→            productTags: topTags,
   241→          }).catch(console.error);
   242→        })
   243→        .catch(console.error);
   244→    }
   245→
   246→    return json(
   247→      {
   248→        sessionId,
   249→        resultPage: {
   250→          id: matchedResultPage.id,
   251→          title: matchedResultPage.title,
   252→          description: matchedResultPage.description,
   253→          showDiscount: matchedResultPage.showDiscount,
   254→          discountCode: matchedResultPage.discountCode,
   255→          discountType: matchedResultPage.discountType,
   256→          discountValue: matchedResultPage.discountValue,
   257→          ctaText: matchedResultPage.ctaText,
   258→          ctaUrl: matchedResultPage.ctaUrl,
   259→          layout: matchedResultPage.layout,
   260→        },
   261→        score: totalScore,
   262→        recommendedProducts: products.map((p) => ({
   263→          gid: p.productGid,
   264→          title: p.title,
   265→          imageUrl: p.imageUrl,
   266→          handle: p.handle,
   267→          priceMin: p.priceMin,
   268→          priceMax: p.priceMax,
   269→        })),
   270→      },
   271→      { headers: CORS_HEADERS },
   272→    );
   273→  } catch (error) {
   274→    console.error("Quiz submit error:", error);
   275→    return json(
   276→      { error: "Internal server error" },
   277→      { status: 500, headers: CORS_HEADERS },
   278→    );
   279→  }
   280→}
