   154→        shop: session.shop,
   155→        planId,
   156→        status: "active",
   157→        quizLimit: limits.quizLimit,
   158→        responseLimit: limits.responseLimit,
   159→      },
   160→      update: {
   161→        planId,
   162→        status: "active",
   163→        quizLimit: limits.quizLimit,
   164→        responseLimit: limits.responseLimit,
   165→      },
   166→    });
   167→
   168→    const planName = PLANS.find((p) => p.id === planId)?.name ?? planId;
   169→    const message =
