    10→function parseSafe<T>(str: string, fallback: T): T {
    11→  try {
    12→    return JSON.parse(str) as T;
    13→  } catch {
    14→    return fallback;
    15→  }
    16→}
    17→
    18→export async function loader({ request, params }: LoaderFunctionArgs) {
    19→  if (request.method === "OPTIONS") {
    20→    return new Response(null, { status: 204, headers: CORS_HEADERS });
    21→  }
    22→
    23→  const { slug } = params;
    24→  const shop = new URL(request.url).searchParams.get("shop");
    25→
    26→  if (!slug || !shop) {
    27→    return json(
    28→      { error: "Missing slug or shop parameter" },
    29→      { status: 400, headers: CORS_HEADERS },
    30→    );
    31→  }
    32→
    33→  // Validate shop domain format
    34→  if (!/^[a-z0-9-]+\.myshopify\.com$/.test(shop)) {
    35→    return json(
    36→      { error: "Invalid shop domain" },
    37→      { status: 400, headers: CORS_HEADERS },
    38→    );
    39→  }
    40→
    41→  try {
    42→    const quiz = await db.quiz.findFirst({
    43→      where: { shop, slug, status: "active" },
    44→      include: {
    45→        questions: {
    46→          include: { answers: { orderBy: { position: "asc" } } },
    47→          orderBy: { position: "asc" },
    48→        },
    49→        resultPages: { orderBy: { position: "asc" } },
    50→      },
    51→    });
    52→
    53→    if (!quiz) {
    54→      return json(
    55→        { error: "Quiz not found or not active" },
    56→        { status: 404, headers: CORS_HEADERS },
    57→      );
    58→    }
    59→
    60→    // Increment start count — fire and forget, non-blocking
    61→    db.quiz
    62→      .update({ where: { id: quiz.id }, data: { startCount: { increment: 1 } } })
    63→      .catch(() => {});
    64→
    65→    return json(
    66→      {
    67→        id: quiz.id,
    68→        title: quiz.title,
    69→        description: quiz.description,
    70→        slug: quiz.slug,
    71→        settings: parseSafe(quiz.settings, {}),
    72→        styling: parseSafe(quiz.styling, {}),
    73→        questions: quiz.questions.map((q) => ({
    74→          id: q.id,
    75→          type: q.type,
    76→          title: q.title,
    77→          description: q.description,
    78→          imageUrl: q.imageUrl,
    79→          required: q.required,
    80→          position: q.position,
    81→          settings: parseSafe(q.settings, {}),
    82→          logic: parseSafe(q.logic, { rules: [] }),
    83→          answers: q.answers.map((a) => ({
    84→            id: a.id,
    85→            text: a.text,
    86→            imageUrl: a.imageUrl,
    87→            position: a.position,
    88→            score: a.score,
    89→            productTags: parseSafe(a.productTags, [] as string[]),
    90→          })),
    91→        })),
    92→        resultPages: quiz.resultPages.map((r) => ({
    93→          id: r.id,
    94→          title: r.title,
    95→          description: r.description,
    96→          type: r.type,
    97→          minScore: r.minScore,
    98→          maxScore: r.maxScore,
    99→          matchTags: parseSafe(r.matchTags, [] as string[]),
   100→          productLimit: r.productLimit,
   101→          layout: r.layout,
   102→          showDiscount: r.showDiscount,
   103→          discountType: r.discountType,
   104→          discountValue: r.discountValue,
   105→          discountCode: r.discountCode,
   106→          ctaText: r.ctaText,
   107→          ctaUrl: r.ctaUrl,
   108→        })),
   109→      },
   110→      { headers: CORS_HEADERS },
   111→    );
   112→  } catch (error) {
   113→    console.error("Quiz API error:", error);
   114→    return json(
   115→      { error: "Internal server error" },
   116→      { status: 500, headers: CORS_HEADERS },
   117→    );
   118→  }
   119→}
