   274→        }
   275→      }, index * 750);
   276→      timers.push(timer);
   277→    });
   278→
   279→    // Mark last step complete and navigate
   280→    const finalTimer = setTimeout(() => {
   281→      setCompletedSteps((prev) => [...prev, progressSteps.length - 1]);
   282→    }, progressSteps.length * 750);
   283→    timers.push(finalTimer);
   284→
   285→    const navTimer = setTimeout(() => {
   286→      onComplete();
   287→    }, progressSteps.length * 750 + 500);
   288→    timers.push(navTimer);
   289→
   290→    return () => timers.forEach(clearTimeout);
   291→  }, [onComplete]);
