   385→              ))}
   386→            </BlockStack>
   387→            <Button onClick={onAddQuestion} fullWidth>
   388→              + Add question
   389→            </Button>
   390→          </BlockStack>
   391→        </Card>
   392→      </Layout.Section>
   393→
   394→      {/* Right panel — question editor */}
   395→      <Layout.Section>
   396→        <Card>
