   437→                      tone="critical"
   438→                      variant="plain"
   439→                      onClick={() => onDeleteOption(option.id)}
   440→                    >
   441→                      Delete
   442→                    </Button>
   443→                  </InlineStack>
   444→                ))}
   445→              </BlockStack>
   446→              <Button onClick={onAddOption}>+ Add answer</Button>
   447→            </BlockStack>
   448→          ) : (
   449→            <Text as="p" variant="bodyMd" tone="subdued">
   450→              Select a question from the sidebar to edit it.
   451→            </Text>
   452→          )}
   453→        </Card>
   454→      </Layout.Section>
   455→    </Layout>
   456→  );
   457→}
