   459→// --- Tab: Product Mapping ---
   460→
   461→function ProductMappingTab({
   462→  questions,
   463→  onAddProduct,
   464→  onRemoveProduct,
   465→}: {
   466→  questions: Question[];
   467→  onAddProduct: (questionId: string, optionId: string, product: string) => void;
   468→  onRemoveProduct: (
   469→    questionId: string,
   470→    optionId: string,
   471→    product: string,
   472→  ) => void;
   473→}) {
   474→  const [browseValue, setBrowseValue] = useState<Record<string, string>>({});
   475→
   476→  return (
   477→    <BlockStack gap="600">
   478→      {questions.map((question) => (
   479→        <Card key={question.id}>
   480→          <BlockStack gap="400">
   481→            <Text as="h3" variant="headingSm" fontWeight="semibold">
   482→              {question.title}
   483→            </Text>
   484→            <Divider />
   485→            <BlockStack gap="400">
   486→              {question.options.map((option) => {
   487→                const fieldKey = `${question.id}-${option.id}`;
   488→                return (
   489→                  <BlockStack key={option.id} gap="200">
   490→                    <Text as="p" variant="bodyMd" fontWeight="medium">
   491→                      {option.label}
   492→                    </Text>
   493→                    <InlineStack gap="200" blockAlign="end">
   494→                      <div style={{ flex: 1 }}>
   495→                        <TextField
   496→                          label=""
   497→                          labelHidden
   498→                          value={browseValue[fieldKey] ?? ""}
   499→                          onChange={(value) =>
   500→                            setBrowseValue((prev) => ({
   501→                              ...prev,
   502→                              [fieldKey]: value,
   503→                            }))
   504→                          }
   505→                          autoComplete="off"
   506→                          placeholder="Add a product tag..."
   507→                        />
   508→                      </div>
   509→                      <Button
   510→                        onClick={() => {
   511→                          const value = browseValue[fieldKey];
   512→                          if (value?.trim()) {
   513→                            onAddProduct(
   514→                              question.id,
   515→                              option.id,
   516→                              value.trim(),
   517→                            );
   518→                            setBrowseValue((prev) => ({
   519→                              ...prev,
   520→                              [fieldKey]: "",
   521→                            }));
   522→                          }
   523→                        }}
   524→                      >
   525→                        Add tag
   526→                      </Button>
   527→                    </InlineStack>
   528→                    {option.productTags.length > 0 && (
   529→                      <InlineStack gap="200">
   530→                        {option.productTags.map((tag) => (
   531→                          <Tag
   532→                            key={tag}
   533→                            onRemove={() =>
   534→                              onRemoveProduct(question.id, option.id, tag)
   535→                            }
   536→                          >
   537→                            {tag}
   538→                          </Tag>
   539→                        ))}
   540→                      </InlineStack>
   541→                    )}
   542→                  </BlockStack>
   543→                );
   544→              })}
   545→            </BlockStack>
   546→          </BlockStack>
   547→        </Card>
   548→      ))}
   549→    </BlockStack>
   550→  );
   551→}
