   694→// --- Main Page ---
   695→
   696→export default function QuizBuilder() {
   697→  const loaderData = useLoaderData<typeof loader>();
   698→  const actionData = useActionData<typeof action>();
   699→  const navigate = useNavigate();
   700→  const submit = useSubmit();
   701→  const shopify = useAppBridge();
   702→
   703→  const { quiz, questions: initialQuestions, designSettings: initialDesign } =
   704→    loaderData;
   705→
   706→  const [questions, setQuestions] = useState<Question[]>(initialQuestions);
   707→  const [selectedQuestionIndex, setSelectedQuestionIndex] = useState(0);
   708→  const [design, setDesign] = useState<DesignSettings>(initialDesign);
   709→  const [selectedTab, setSelectedTab] = useState(0);
   710→  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
   711→
   712→  const quizId = quiz.id;
   713→
   714→  // Show toast on every action result
   715→  useEffect(() => {
   716→    if (!actionData) return;
   717→    if ("success" in actionData && actionData.success && "message" in actionData) {
   718→      shopify.toast.show(String(actionData.message), { duration: 3000 });
   719→    } else if ("error" in actionData && actionData.error) {
   720→      shopify.toast.show(String(actionData.error), {
   721→        duration: 4000,
   722→        isError: true,
   723→      });
   724→    }
   725→  }, [actionData, shopify]);
   726→
   727→  const tabs = [
   728→    { id: "questions", content: "Questions", panelID: "questions-panel" },
   729→    { id: "mapping", content: "Product Mapping", panelID: "mapping-panel" },
   730→    { id: "design", content: "Design", panelID: "design-panel" },
   731→  ];
   732→
   733→  const handleTabChange = useCallback((index: number) => {
   734→    setSelectedTab(index);
   735→  }, []);
   736→
   737→  // Save questions tab
   738→  const handleSaveQuestions = useCallback(() => {
   739→    const formData = new FormData();
   740→    formData.set("intent", "save-questions");
   741→    formData.set(
   742→      "questions",
   743→      JSON.stringify(
   744→        questions.map((q, qi) => ({
   745→          id: q.id,
   746→          title: q.title,
   747→          type: q.type,
   748→          required: q.required,
   749→          position: qi,
   750→          options: q.options.map((o, oi) => ({
   751→            id: o.id,
   752→            label: o.label,
   753→            score: o.score,
   754→            productTags: o.productTags,
   755→            position: oi,
   756→          })),
   757→        })),
   758→      ),
   759→    );
   760→    submit(formData, { method: "POST" });
   761→  }, [questions, submit]);
   762→
   763→  // Save design tab
   764→  const handleSaveDesign = useCallback(() => {
   765→    const stylingObj = {
   766→      buttonColor: design.buttonColor,
   767→      buttonText: design.buttonText,
   768→      resultsHeading: design.resultsHeading,
   769→      showProgressBar: design.showProgressBar,
   770→    };
   771→    const formData = new FormData();
   772→    formData.set("intent", "save-design");
   773→    formData.set("title", design.quizTitle);
   774→    formData.set("description", design.description);
   775→    formData.set("styling", JSON.stringify(stylingObj));
   776→    submit(formData, { method: "POST" });
   777→  }, [design, submit]);
   778→
   779→  const handlePublish = useCallback(() => {
   780→    const formData = new FormData();
   781→    formData.set("intent", "publish");
   782→    submit(formData, { method: "POST" });
   783→  }, [submit]);
   784→
   785→  const handleUnpublish = useCallback(() => {
   786→    const formData = new FormData();
   787→    formData.set("intent", "unpublish");
   788→    submit(formData, { method: "POST" });
   789→  }, [submit]);
   790→
   791→  const handleDeleteConfirm = useCallback(() => {
   792→    const formData = new FormData();
   793→    formData.set("intent", "delete");
   794→    submit(formData, { method: "POST" });
   795→  }, [submit]);
   796→
   797→  const handlePreview = useCallback(() => {
   798→    navigate(`/app/quizzes/${quizId}/preview`);
   799→  }, [navigate, quizId]);
   800→
   801→  const handleBack = useCallback(() => {
   802→    navigate("/app/quizzes");
   803→  }, [navigate]);
   804→
   805→  // --- Question handlers ---
   806→
   807→  const handleSelectQuestion = useCallback((index: number) => {
   808→    setSelectedQuestionIndex(index);
   809→  }, []);
   810→
   811→  const handleUpdateQuestion = useCallback(
   812→    (field: string, value: string | boolean) => {
   813→      setQuestions((prev) => {
   814→        const updated = [...prev];
   815→        updated[selectedQuestionIndex] = {
   816→          ...updated[selectedQuestionIndex],
   817→          [field]: value,
   818→        };
   819→        return updated;
   820→      });
   821→    },
   822→    [selectedQuestionIndex],
   823→  );
   824→
   825→  const handleAddQuestion = useCallback(() => {
   826→    const newId = `new-${Date.now()}`;
   827→    const newQuestion: Question = {
   828→      id: newId,
   829→      title: "",
   830→      type: "single",
   831→      required: true,
   832→      position: questions.length,
   833→      options: [
   834→        { id: `${newId}a1`, label: "Option 1", score: 0, productTags: [], position: 0 },
   835→        { id: `${newId}a2`, label: "Option 2", score: 0, productTags: [], position: 1 },
   836→      ],
   837→    };
   838→    setQuestions((prev) => [...prev, newQuestion]);
   839→    setSelectedQuestionIndex(questions.length);
   840→  }, [questions.length]);
   841→
   842→  const handleAddOption = useCallback(() => {
   843→    setQuestions((prev) => {
   844→      const updated = [...prev];
   845→      const question = { ...updated[selectedQuestionIndex] };
   846→      const newOptionId = `${question.id}a${Date.now()}`;
   847→      question.options = [
   848→        ...question.options,
   849→        {
   850→          id: newOptionId,
   851→          label: "",
   852→          score: 0,
   853→          productTags: [],
   854→          position: question.options.length,
   855→        },
   856→      ];
   857→      updated[selectedQuestionIndex] = question;
   858→      return updated;
   859→    });
   860→  }, [selectedQuestionIndex]);
   861→
   862→  const handleUpdateOption = useCallback(
   863→    (optionId: string, value: string) => {
   864→      setQuestions((prev) => {
   865→        const updated = [...prev];
   866→        const question = { ...updated[selectedQuestionIndex] };
   867→        question.options = question.options.map((opt) =>
   868→          opt.id === optionId ? { ...opt, label: value } : opt,
   869→        );
   870→        updated[selectedQuestionIndex] = question;
   871→        return updated;
   872→      });
   873→    },
   874→    [selectedQuestionIndex],
   875→  );
   876→
   877→  const handleDeleteOption = useCallback(
   878→    (optionId: string) => {
   879→      setQuestions((prev) => {
   880→        const updated = [...prev];
   881→        const question = { ...updated[selectedQuestionIndex] };
