   883→          (opt) => opt.id !== optionId,
   884→        );
   885→        updated[selectedQuestionIndex] = question;
   886→        return updated;
   887→      });
   888→    },
   889→    [selectedQuestionIndex],
   890→  );
   891→
   892→  // --- Product mapping handlers ---
   893→
   894→  const handleAddProduct = useCallback(
   895→    (questionId: string, optionId: string, tag: string) => {
   896→      setQuestions((prev) =>
   897→        prev.map((q) =>
   898→          q.id === questionId
   899→            ? {
   900→                ...q,
   901→                options: q.options.map((opt) =>
   902→                  opt.id === optionId
   903→                    ? {
   904→                        ...opt,
   905→                        productTags: [...opt.productTags, tag],
   906→                      }
   907→                    : opt,
   908→                ),
   909→              }
   910→            : q,
   911→        ),
   912→      );
   913→    },
   914→    [],
   915→  );
   916→
   917→  const handleRemoveProduct = useCallback(
   918→    (questionId: string, optionId: string, tag: string) => {
   919→      setQuestions((prev) =>
   920→        prev.map((q) =>
   921→          q.id === questionId
   922→            ? {
   923→                ...q,
   924→                options: q.options.map((opt) =>
   925→                  opt.id === optionId
   926→                    ? {
   927→                        ...opt,
   928→                        productTags: opt.productTags.filter((t) => t !== tag),
   929→                      }
   930→                    : opt,
   931→                ),
   932→              }
   933→            : q,
   934→        ),
   935→      );
   936→    },
   937→    [],
   938→  );
   939→
   940→  // --- Design handlers ---
   941→
   942→  const handleUpdateDesign = useCallback(
   943→    (field: keyof DesignSettings, value: string | boolean) => {
   944→      setDesign((prev) => ({ ...prev, [field]: value }));
   945→    },
   946→    [],
   947→  );
   948→
   949→  // Current save action depends on active tab
   950→  const handleSave = useCallback(() => {
   951→    if (selectedTab === 2) {
   952→      handleSaveDesign();
   953→    } else {
   954→      handleSaveQuestions();
   955→    }
   956→  }, [selectedTab, handleSaveDesign, handleSaveQuestions]);
   957→
   958→  const isLive = quiz.status === "active";
   959→  const statusTone = isLive
   960→    ? "success"
   961→    : quiz.status === "draft"
   962→      ? "attention"
   963→      : undefined;
   964→  const statusLabel = isLive ? "Live" : "Draft";
   965→
   966→  return (
   967→    <>
   968→      <Page
   969→        title={quiz.title}
   970→        backAction={{ content: "Quizzes", onAction: handleBack }}
   971→        titleMetadata={<Badge tone={statusTone}>{statusLabel}</Badge>}
   972→        primaryAction={{
   973→          content: "Save",
   974→          onAction: handleSave,
   975→        }}
   976→        secondaryActions={[
   977→          {
   978→            content: "Preview",
   979→            onAction: handlePreview,
   980→          },
   981→          isLive
   982→            ? {
   983→                content: "Unpublish",
   984→                onAction: handleUnpublish,
   985→              }
   986→            : {
   987→                content: "Publish",
   988→                onAction: handlePublish,
   989→              },
   990→          {
   991→            content: "Delete",
   992→            destructive: true,
   993→            onAction: () => setDeleteModalOpen(true),
   994→          },
   995→        ]}
   996→      >
   997→        <BlockStack gap="400">
   998→          <Card padding="0">
   999→            <Tabs tabs={tabs} selected={selectedTab} onSelect={handleTabChange}>
  1000→              <Box padding="400">
  1001→                {selectedTab === 0 && (
  1002→                  <QuestionsTab
  1003→                    questions={questions}
  1004→                    selectedQuestionIndex={selectedQuestionIndex}
  1005→                    onSelectQuestion={handleSelectQuestion}
  1006→                    onUpdateQuestion={handleUpdateQuestion}
  1007→                    onAddQuestion={handleAddQuestion}
  1008→                    onAddOption={handleAddOption}
  1009→                    onUpdateOption={handleUpdateOption}
  1010→                    onDeleteOption={handleDeleteOption}
  1011→                  />
  1012→                )}
  1013→                {selectedTab === 1 && (
  1014→                  <ProductMappingTab
  1015→                    questions={questions}
  1016→                    onAddProduct={handleAddProduct}
  1017→                    onRemoveProduct={handleRemoveProduct}
  1018→                  />
  1019→                )}
  1020→                {selectedTab === 2 && (
  1021→                  <DesignTab
  1022→                    design={design}
  1023→                    onUpdateDesign={handleUpdateDesign}
  1024→                  />
  1025→                )}
  1026→              </Box>
  1027→            </Tabs>
  1028→          </Card>
  1029→        </BlockStack>
  1030→      </Page>
  1031→
  1032→      {/* Delete confirmation modal */}
  1033→      <Modal
  1034→        open={deleteModalOpen}
  1035→        onClose={() => setDeleteModalOpen(false)}
  1036→        title="Delete quiz?"
  1037→        primaryAction={{
  1038→          content: "Delete",
  1039→          destructive: true,
  1040→          onAction: handleDeleteConfirm,
  1041→        }}
  1042→        secondaryActions={[
  1043→          {
  1044→            content: "Cancel",
  1045→            onAction: () => setDeleteModalOpen(false),
  1046→          },
  1047→        ]}
  1048→      >
  1049→        <Modal.Section>
  1050→          <Text as="p" variant="bodyMd">
  1051→            Are you sure you want to delete <strong>{quiz.title}</strong>? This
  1052→            will permanently delete the quiz, all its questions, answers, and
  1053→            response data. This action cannot be undone.
  1054→          </Text>
  1055→        </Modal.Section>
  1056→      </Modal>
  1057→    </>
  1058→  );
  1059→}
