   146→// ─── Action ───────────────────────────────────────────────────────────────────
   147→
   148→export const action = async ({ request }: ActionFunctionArgs) => {
   149→  const { session } = await authenticate.admin(request);
   150→  const formData = await request.formData();
   151→  const intent = String(formData.get("intent") ?? "");
   152→
   153→  try {
   154→    if (intent !== "save") {
   155→      return json({ error: "Unknown action" }, { status: 400 });
   156→    }
   157→
   158→    const position = String(formData.get("position") ?? "embedded");
   159→    const triggerType = String(formData.get("triggerType") ?? "button");
   160→
   161→    // Build triggerValue based on type
   162→    const triggerValue: TriggerValue = {};
   163→    if (triggerType === "scroll") {
   164→      const depth = String(formData.get("scrollDepth") ?? "").trim();
   165→      if (depth) triggerValue.scrollDepth = depth;
   166→    } else if (triggerType === "timer") {
   167→      const delay = String(formData.get("delaySeconds") ?? "").trim();
   168→      if (delay) triggerValue.delaySeconds = delay;
   169→    }
   170→
   171→    const primaryColor = String(formData.get("primaryColor") ?? "#5C6AC4").trim() || "#5C6AC4";
   172→    const borderRadius = String(formData.get("borderRadius") ?? "8").trim() || "8";
   173→    const fontSize = String(formData.get("fontSize") ?? "16").trim() || "16";
   174→    const showPoweredBy = formData.get("showPoweredBy") === "true";
   175→    const logoUrl = String(formData.get("logoUrl") ?? "").trim() || undefined;
   176→    const customCssRaw = String(formData.get("customCss") ?? "").trim();
   177→
   178→    const updates = {
   179→      position,
   180→      triggerType,
   181→      triggerValue: JSON.stringify(triggerValue),
   182→      styling: JSON.stringify({ primaryColor, borderRadius, fontSize }),
   183→      branding: JSON.stringify({ showPoweredBy, ...(logoUrl ? { logoUrl } : {}) }),
   184→      customCss: customCssRaw || null,
   185→      updatedAt: new Date(),
   186→    };
   187→
   188→    await db.widgetConfig.upsert({
   189→      where: { shop: session.shop },
   190→      create: { shop: session.shop, ...updates },
   191→      update: updates,
   192→    });
   193→
   194→    return json({ success: true, message: "Widget settings saved." });
   195→  } catch (error) {
   196→    if (error instanceof Response) throw error;
   197→    console.error("Widget action failed:", error);
   198→    return json({ error: "Failed to save widget settings." }, { status: 500 });
   199→  }
   200→};
