   177→// ─── Action ───────────────────────────────────────────────────────────────────
   178→
   179→export const action = async ({ request, params }: ActionFunctionArgs) => {
   180→  const { session } = await authenticate.admin(request);
   181→  const quizId = params.id!;
   182→  const formData = await request.formData();
   183→  const intent = String(formData.get("intent") ?? "");
   184→
   185→  try {
   186→    // Verify quiz ownership before any mutation
   187→    const quiz = await db.quiz.findFirst({
   188→      where: { id: quizId, shop: session.shop },
   189→    });
   190→    if (!quiz) {
   191→      return json({ error: "Quiz not found" }, { status: 404 });
   192→    }
   193→
   194→    switch (intent) {
   195→      case "create": {
   196→        const title = String(formData.get("title") ?? "Result Page").trim() || "Result Page";
   197→        const type = String(formData.get("type") ?? "default");
   198→        const count = await db.resultPage.count({ where: { quizId } });
   199→        await db.resultPage.create({
   200→          data: {
   201→            quizId,
   202→            title,
   203→            type,
   204→            position: count,
   205→          },
   206→        });
   207→        return json({ success: true, message: "Result page created." });
   208→      }
   209→
   210→      case "update": {
   211→        const pageId = String(formData.get("pageId") ?? "").trim();
   212→        if (!pageId) {
   213→          return json({ error: "Missing page ID" }, { status: 400 });
   214→        }
   215→
   216→        // Verify page belongs to this quiz (which we already confirmed belongs to shop)
   217→        const existingPage = await db.resultPage.findFirst({
   218→          where: { id: pageId, quizId },
   219→        });
   220→        if (!existingPage) {
   221→          return json({ error: "Result page not found" }, { status: 404 });
   222→        }
   223→
   224→        const title = String(formData.get("title") ?? "").trim();
   225→        const description = String(formData.get("description") ?? "").trim() || null;
   226→        const type = String(formData.get("type") ?? "default");
   227→        const layout = String(formData.get("layout") ?? "grid");
   228→        const productLimit = parseInt(String(formData.get("productLimit") ?? "4"), 10);
   229→        const showDiscount = formData.get("showDiscount") === "true";
   230→        const ctaText = String(formData.get("ctaText") ?? "").trim() || null;
   231→        const ctaUrl = String(formData.get("ctaUrl") ?? "").trim() || null;
   232→
   233→        // Score-range fields
   234→        const minScoreRaw = formData.get("minScore");
   235→        const maxScoreRaw = formData.get("maxScore");
   236→        const minScore =
   237→          minScoreRaw !== null && String(minScoreRaw).trim() !== ""
   238→            ? parseInt(String(minScoreRaw), 10)
   239→            : null;
   240→        const maxScore =
   241→          maxScoreRaw !== null && String(maxScoreRaw).trim() !== ""
   242→            ? parseInt(String(maxScoreRaw), 10)
   243→            : null;
   244→
   245→        // Tag-match fields
   246→        const matchTagsRaw = String(formData.get("matchTags") ?? "")
   247→          .split(",")
   248→          .map((t) => t.trim())
   249→          .filter(Boolean);
   250→        const matchTags = JSON.stringify(matchTagsRaw);
   251→
   252→        // Discount fields
   253→        const discountType = showDiscount
   254→          ? String(formData.get("discountType") ?? "percentage") || null
   255→          : null;
   256→        const discountValueRaw = formData.get("discountValue");
   257→        const discountValue =
   258→          showDiscount && discountValueRaw !== null && String(discountValueRaw).trim() !== ""
   259→            ? parseFloat(String(discountValueRaw))
   260→            : null;
   261→        const discountCode = showDiscount
   262→          ? String(formData.get("discountCode") ?? "").trim() || null
   263→          : null;
   264→
   265→        if (!title) {
   266→          return json({ error: "Title is required" }, { status: 400 });
   267→        }
   268→
   269→        await db.resultPage.update({
   270→          where: { id: pageId },
   271→          data: {
   272→            title,
   273→            description,
   274→            type,
   275→            minScore: type === "score-range" ? minScore : null,
   276→            maxScore: type === "score-range" ? maxScore : null,
   277→            matchTags: type === "tag-match" ? matchTags : "[]",
   278→            layout,
   279→            productLimit: isNaN(productLimit) ? 4 : productLimit,
   280→            showDiscount,
   281→            discountType,
   282→            discountValue,
   283→            discountCode,
   284→            ctaText,
   285→            ctaUrl,
   286→            updatedAt: new Date(),
   287→          },
   288→        });
   289→
   290→        return json({ success: true, message: "Result page saved." });
   291→      }
   292→
   293→      case "delete": {
   294→        const pageId = String(formData.get("pageId") ?? "").trim();
   295→        if (!pageId) {
   296→          return json({ error: "Missing page ID" }, { status: 400 });
   297→        }
   298→
   299→        // Verify page belongs to this quiz
   300→        const page = await db.resultPage.findFirst({
   301→          where: { id: pageId, quizId },
   302→        });
   303→        if (!page) {
   304→          return json({ error: "Result page not found" }, { status: 404 });
   305→        }
   306→
   307→        await db.resultPage.delete({ where: { id: pageId } });
   308→
   309→        // Re-index positions after delete
   310→        const remaining = await db.resultPage.findMany({
   311→          where: { quizId },
   312→          orderBy: { position: "asc" },
   313→        });
   314→        await Promise.all(
   315→          remaining.map((p, idx) =>
   316→            db.resultPage.update({ where: { id: p.id }, data: { position: idx } })
   317→          )
   318→        );
   319→
   320→        return json({ success: true, message: "Result page deleted." });
   321→      }
   322→
   323→      case "reorder": {
   324→        const orderJson = String(formData.get("order") ?? "[]");
   325→        let order: string[];
   326→        try {
   327→          order = JSON.parse(orderJson) as string[];
   328→        } catch {
   329→          return json({ error: "Invalid order data" }, { status: 400 });
   330→        }
   331→        await Promise.all(
   332→          order.map((pageId, idx) =>
   333→            db.resultPage.updateMany({
   334→              where: { id: pageId, quizId },
   335→              data: { position: idx },
   336→            })
   337→          )
   338→        );
   339→        return json({ success: true, message: "Order updated." });
   340→      }
   341→
   342→      default:
   343→        return json({ error: "Unknown action" }, { status: 400 });
   344→    }
   345→  } catch (error) {
   346→    if (error instanceof Response) throw error;
   347→    console.error(`Results action "${intent}" failed:`, error);
   348→    return json({ error: "Action failed. Please try again." }, { status: 500 });
   349→  }
   350→};
