     1→import db from "~/db.server";
     2→import { PLAN_LIMITS, type PlanId } from "~/utils/constants";
     3→import { data } from "react-router";
     4→
     5→export async function getSubscription(shop: string) {
     6→  return db.subscription.findUnique({ where: { shop } });
     7→}
     8→
     9→export async function getPlanId(shop: string): Promise<PlanId> {
    10→  const sub = await db.subscription.findUnique({
    11→    where: { shop },
    12→    select: { planId: true, status: true },
    13→  });
    14→  if (!sub || sub.status !== "active") return "free";
    15→  const validPlans = Object.keys(PLAN_LIMITS) as PlanId[];
    16→  return validPlans.includes(sub.planId as PlanId)
    17→    ? (sub.planId as PlanId)
    18→    : "free";
    19→}
    20→
    21→export async function requirePlan(
    22→  shop: string,
    23→  minimumPlan: PlanId
    24→): Promise<void> {
    25→  const planOrder: PlanId[] = ["free", "starter", "pro", "enterprise"];
    26→  const currentPlan = await getPlanId(shop);
    27→  if (planOrder.indexOf(currentPlan) < planOrder.indexOf(minimumPlan)) {
    28→    throw data(
    29→      {
    30→        error: `This feature requires the ${minimumPlan} plan or higher.`,
    31→        requiredPlan: minimumPlan,
    32→        currentPlan,
    33→      },
    34→      { status: 403 }
    35→    );
    36→  }
    37→}
    38→
    39→export async function checkQuizLimit(shop: string): Promise<void> {
    40→  const planId = await getPlanId(shop);
    41→  const limit = PLAN_LIMITS[planId].quizLimit;
    42→  if (limit === Infinity) return;
    43→  const count = await db.quiz.count({
    44→    where: { shop, status: { not: "archived" } },
    45→  });
    46→  if (count >= limit) {
    47→    throw data(
    48→      {
    49→        error: `You've reached the ${limit}-quiz limit for the ${planId} plan.`,
    50→        currentPlan: planId,
    51→        limit,
    52→        current: count,
    53→      },
    54→      { status: 403 }
    55→    );
    56→  }
    57→}
    58→
    59→export async function ensureSubscription(shop: string) {
    60→  return db.subscription.upsert({
    61→    where: { shop },
    62→    create: {
    63→      shop,
    64→      planId: "free",
    65→      status: "active",
    66→      quizLimit: 1,
    67→      responseLimit: 100,
    68→    },
    69→    update: {},
    70→  });
    71→}
